import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>ওয়েবসাইট ধীর লাগছে? ছবিগুলোই প্রায়ই কারণ৤ এই ধাপে ধাপে গাইডে আপনি শিখবেন কীভাবে ছবি অপটিমাইজ করে পাতা দ্রুত করবেন৤</p>\n<p>প্রক্রিয়াটি সহজ, তবে ক্রমটি গুরুত্বপূর্ণ৤ প্রথমে অডিট করুন, তারপর অপটিমাইজ করুন, তারপর ফল মাপুন৤</p>\n<p>শুরু থেকে শেষ পর্যন্ত প্রতিটি ধাপ এখানে দেওয়া হলো, সঙ্গে ব্লগ আর দোকানের জন্য আলাদা পরামর্শও আছে৤</p>\n<h2 id=\"audit-first\">প্রথমে অডিট করুন</h2>\n<p>অপটিমাইজ করার আগে পাতার বর্তমান অবস্থা দেখুন৤ PageSpeed Insights দিয়ে গতি পরীক্ষা করুন৤</p>\n<p>কোন ছবিগুলো সবচেয়ে বড়, তা দেখুন৤ বড় ছবিগুলোই প্রথমে ঠিক করুন৤</p>\n<p>অডিটের ফল লিখে রাখুন৤ পরে তুলনা করে বুঝতে পারবেন কতটা উন্নতি হলো৤</p>\n<h2 id=\"step-2-open\">ধাপ ২: অপটিমাইজার খুলুন</h2>\n<p>ব্রাউজারে <a href=\"/bn/web-image-optimizer\">ওয়েব ইমেজ অপটিমাইজার</a> খুলুন৤ পাতাটি লোড হলেই আপলোড এলাকা দেখতে পাবেন৤</p>\n<p>টুলটি আপনার ডিভাইসেই চলে, তাই ছবি কোথাও আপলোড হয় না৤</p>\n<p>ফোনে হলে বোতামটি বড় দেখায়৤ ডেস্কটপে ছবি টেনে ছেড়ে দেওয়া যায়৤</p>\n<h2 id=\"step-3-preset\">ধাপ ৩: প্রিসেট বেছে নিন</h2>\n<p>ছবিটি কোথায় ব্যবহার হবে, সেই অনুযায়ী প্রিসেট বেছে নিন৤ হিরো ছবির জন্য হিরো প্রিসেট, থাম্বনেইলের জন্য থাম্বনেইল প্রিসেট৤</p>\n<p>প্রিসেট ভুল হলে ছবি অযথা বড় বা খারাপ হতে পারে৤ তাই প্রিসেট বেছে নেওয়ার আগে ভাবুন৤</p>\n<p>অনিশ্চিত হলে মাঝামাঝি প্রিসেট নিন৤ পরে প্রয়োজনে আলাদাভাবে ঠিক করা যায়৤</p>\n<h2 id=\"step-4-upload\">ধাপ ৪: ছবি আপলোড করুন</h2>\n<p>ছবিটি আপলোড এলাকায় ছেড়ে দিন বা বোতামে ট্যাপ করে গ্যালারি থেকে বেছে নিন৤</p>\n<p>JPG, PNG, WebP আর HEIC সবই চলে৤ 25MB পর্যন্ত ফাইল নেওয়া হয়৤</p>\n<p>একসঙ্গে অনেক ছবি আপলোড করা যায়৤ ব্যাচে করলে সময় বাঁচে৤</p>\n<p>আপলোড করার সময় মূল ছবি ব্যবহার করুন৤ আগেরবার কমপ্রেস করা ফাইল আপলোড করলে মান আরও কমে৤ মূল ফাইল থেকে শুরু করলে সেরা ফল পাওয়া যায়৤</p>\n<p>আপলোডের আগে ফাইলের নাম দেখুন৤ নামে ছবির বিষয় থাকলে পরে খুঁজে পাওয়া সহজ হয়৤ IMG_1234-এর মতো নাম বদলে বিষয় অনুযায়ী নাম দিন৤</p>\n<p>বড় ফাইল আপলোড করতে ধীর ইন্টারনেটে সময় লাগে৤ ১০MB ছবি আপলোডে এক মিনিট পর্যন্ত লাগতে পারে৤ আপলোড শেষ না হওয়া পর্যন্ত অপেক্ষা করুন৤</p>\n<p>ফোন থেকে আপলোড করলে গ্যালারি থেকে ছবি বেছে নিন৤ ফোনের গ্যালারিতে ছবির মূল কপি থাকে৤ স্ক্রিনশট নিয়ে আপলোড করলে মান কমে যায়৤</p>\n<p>একসঙ্গে অনেক ছবি আপলোড করলে প্রতিটি ছবির প্রিসেট একই থাকে৤ ভিন্ন প্রিসেট দরকার হলে ছবিগুলো আলাদা ব্যাচে আপলোড করুন৤ এক ব্যাচে এক প্রিসেট রাখা সহজ৤</p>\n<p>আপলোডের পর ছবির থাম্বনেইল দেখে নিন৤ ভুল ছবি আপলোড হলে তা মুছে সঠিক ছবি দিন৤ থাম্বনেইল না দেখে এগিয়ে গেলে ভুল ফাইল তৈরি হতে পারে৤</p>\n<p>HEIC ছবি আপলোড করলে টুলটি নিজে থেকে তা পড়ে৤ আলাদা কনভার্ট দরকার হয় না৤ আইফোনের ছবি সরাসরি আপলোড করুন৤</p>\n<p>আপলোড করা ছবি সার্ভারে যায় না৤ সব কাজ আপনার ব্রাউজারেই হয়৤ তাই ব্যক্তিগত ছবি আপলোড করতেও নিরাপদ৤ পাতা বন্ধ করলে ছবি মুছে যায়৤</p>\n<p>আপলোড ব্যর্থ হলে ফাইলের আকার দেখুন৤ ২০MB-এর বেশি ফাইল টুলটি নাও নিতে পারে৤ বড় ফাইল প্রথমে একটু ছোট করে আবার আপলোড করুন৤</p>\n<h2 id=\"step-5-customise\">ধাপ ৫: সেটিং ঠিক করুন</h2>\n<p>প্রিসেটের পর কোয়ালিটি স্লাইডার দেখুন৤ ওয়েবসাইটের ছবির জন্য 75 থেকে 85 ভালো৤</p>\n<p>মাপ দেখুন৤ যে মাপে ছবি দেখানো হবে, সেই মাপে রাখুন৤ বাড়তি মাপ শুধু ফাইল বড় করে৤</p>\n<p>ফরম্যাট দেখুন৤ ওয়েবসাইটের জন্য WebP ভালো, তবে পুরোনো ব্রাউজারের জন্য JPG ফলব্যাক রাখুন৤</p>\n<h2 id=\"step-6-preview\">ধাপ ৬: ফল দেখে নিন</h2>\n<p>ডাউনলোডের আগে ছবিটি জুম করে দেখুন৤ মান ঠিক আছে কি না নিশ্চিত করুন৤</p>\n<p>মূল আর নতুন আকার তুলনা করুন৤ কতটা কমল তা দেখুন৤</p>\n<p>ছবি খারাপ লাগলে কোয়ালিটি বাড়িয়ে আবার চেষ্টা করুন৤</p>\n<h2 id=\"step-7-copy-html\">ধাপ ৭: HTML কপি করুন</h2>\n<p>অপটিমাইজার থেকে HTML কোড কপি করা যায়৤ এতে ছবির আকার, alt টেক্সট আর লোডিং সেটিং থাকে৤</p>\n<p>কোডটি আপনার ওয়েবসাইটে বসান৤ এতে কোড লেখার সময় বাঁচে৤</p>\n<p>কোড বসানোর আগে একবার দেখে নিন৤ Alt টেক্সট ঠিক আছে কি না দেখুন৤</p>\n<h2 id=\"step-8-upload\">ধাপ ৮: ওয়েবসাইটে আপলোড করুন</h2>\n<p>অপটিমাইজ করা ছবি ওয়েবসাইটে আপলোড করুন৤ পুরোনো বড় ছবির বদলে নতুন ছবি বসান৤</p>\n<p>আপলোডের পর পাতাটি দেখুন৤ ছবি ঠিক দেখাচ্ছে কি না নিশ্চিত করুন৤</p>\n<p>পুরোনো ছবি মুছে ফেলার আগে নতুনটি পরীক্ষা করুন৤ ভুল ছবি মুছে গেলে সমস্যা হয়৤</p>\n<p>HTML কোড কপি করার আগে ছবির নাম দেখুন৤ নামে ছবির বিষয় থাকলে সার্চ ইঞ্জিন বুঝতে পারে৤ IMG_1234-এর মতো নাম বদলে বিষয় অনুযায়ী নাম দিন৤</p>\n<p>HTML কোডে width আর height থাকে৤ এই দুটি মান ব্রাউজারকে ছবির জায়গা আগে থেকে রাখতে সাহায্য করে৤ লেখা সরে যায় না৤</p>\n<p>HTML কোডে alt টেক্সট থাকে৤ alt টেক্সটে ছবির বিষয় লিখুন৤ সার্চ ইঞ্জিন ছবি খুঁজে পায়, আর দৃষ্টি প্রতিবন্ধী পাঠক ছবিটি বুঝতে পারেন৤</p>\n<p>HTML কোডে loading=\"lazy\" থাকে৤ স্ক্রিনের বাইরের ছবি পরে লোড হয়৤ পাতার প্রথম অংশ দ্রুত দেখা যায়৤</p>\n<p>HTML কোড কপি করার পর আপনার ওয়েবসাইটের এডিটরে বসান৤ কোড বসানোর পর পাতাটি প্রিভিউতে দেখুন৤ ছবি ঠিক জায়গায় আছে কিনা দেখুন৤</p>\n<p>HTML কোডে ছবির লিংক থাকে৤ লিংকটি আপনার সাইটের ছবির ফাইলের দিকে যায়৤ ছবি আপলোড না করলে লিংক ভাঙা দেখায়৤ প্রথমে ছবি আপলোড করুন৤</p>\n<p>HTML কোডে srcset থাকতে পারে৤ srcset-এ ছোট আর বড় স্ক্রিনের জন্য আলাদা ছবি থাকে৤ ব্রাউজার স্ক্রিনের আকার দেখে সঠিক ছবি বেছে নেয়৤</p>\n<p>HTML কোড কপি করার সময় পুরো কোড কপি করুন৤ অর্ধেক কোড কপি করলে ছবি দেখা যায় না৤ কপি বোতামে এক ক্লিকে পুরো কোড কপি হয়৤</p>\n<p>HTML কোড ব্যবহার করার পর পাতার গতি পরীক্ষা করুন৤ PageSpeed Insights-এ পাতার ঠিকানা দিয়ে গতি মাপুন৤ গতি বাড়লে কোড ঠিক আছে৤</p>\n<h2 id=\"fixing-problems\">সমস্যা হলে কী করবেন</h2>\n<p>ছবি ঝাপসা মনে হলে কোয়ালিটি বাড়ান৤ মাপ কমিয়ে কোয়ালিটি বেশি রাখা যায়৤</p>\n<p>পাতা এখনো ধীর হলে অন্য ছবিগুলো দেখুন৤ একটি ছবি ঠিক করলেই পাতা দ্রুত হয় না৤</p>\n<p>ছবি দেখা না গেলে ফরম্যাট দেখুন৤ পুরোনো ব্রাউজারে WebP নাও চলতে পারে৤</p>\n<h2 id=\"blog-workflow\">ব্লগের কাজের ধারা</h2>\n<p>ব্লগের প্রতিটি পোস্টের ছবি একইভাবে অপটিমাইজ করুন৤ এতে ব্লগের গতি একরকম থাকে৤</p>\n<p>হিরো ছবি আর থাম্বনেইল আলাদা প্রিসেটে করুন৤ দুটির লক্ষ্য আলাদা৤</p>\n<p>পুরোনো পোস্টের বড় ছবিগুলোও অপটিমাইজ করে নিন৤ এতে পুরো সাইট দ্রুত হয়৤</p>\n<h2 id=\"shop-workflow\">দোকানের কাজের ধারা</h2>\n<p>দোকানের পণ্যের ছবি একসঙ্গে অপটিমাইজ করুন৤ সব ছবি একই মানে তৈরি হয়৤</p>\n<p>পণ্যের ছবিতে বিবরণ বেশি রাখুন৤ ক্রেতা বিবরণ দেখতে চায়৤</p>\n<p>নতুন পণ্য এলে শুধু সেই ছবিগুলো অপটিমাইজ করুন৤ পুরোনো ছবি আবার করার দরকার নেই৤</p>\n<h2 id=\"speed-tools\">গতি পরীক্ষার টুল</h2>\n<p>PageSpeed Insights দিয়ে পাতার গতি পরীক্ষা করুন৤ এটি ছবির সমস্যা দেখিয়ে দেয়৤</p>\n<p>GTmetrix দিয়েও পরীক্ষা করা যায়৤ এতে পাতার মোট ওজন দেখা যায়৤</p>\n<p>নিয়মিত পরীক্ষা করুন৤ নতুন ছবি যোগ করার সময় গতি দেখুন৤</p>\n<h2 id=\"image-sizes-by-slot\">প্রতিটি জায়গার জন্য ছবির আকার</h2>\n<p>হিরো ছবি বড়, থাম্বনেইল ছোট৤ প্রতিটি জায়গার জন্য আলাদা আকার বানান৤</p>\n<p>একই ছবি সব জায়গায় ব্যবহার করবেন না৤ বড় ছবি ছোট জায়গায় দিলে পাতা ভারী হয়৤</p>\n<p>প্রতিটি জায়গার মাপ লিখে রাখুন৤ নতুন ছবি বানানোর সময় সেই মাপ ব্যবহার করুন৤</p>\n<p>পাতার প্রতিটি জায়গার জন্য ছবির মাপ আলাদা হয়৤ হিরো ছবিতে বড় মাপ দরকার৤ থাম্বনেইলে ছোট মাপ যথেষ্ট৤ জায়গা অনুযায়ী মাপ বেছে নিন৤</p>\n<p>পাতার জায়গা অনুযায়ী ছবির মাপ লিখে রাখুন৤ হিরো ১২০০ পিক্সেল, কার্ড ৬০০ পিক্সেল, আর আইকন ১০০ পিক্সেল৤ তালিকা থাকলে ভুল হয় না৤</p>\n<p>পাতার জায়গার মাপ না জেনে ছবি আপলোড করবেন না৤ বড় ছবি ছোট জায়গায় রাখলে পাতা ধীর হয়৤ ছোট ছবি বড় জায়গায় রাখলে ঝাপসা হয়৤</p>\n<p>পাতার জায়গা অনুযায়ী ছবি তৈরি করতে টুলের প্রিসেট ব্যবহার করুন৤ প্রিসেটে প্রতিটি জায়গার মাপ ঠিক করা থাকে৤ প্রিসেট বেছে নিলে মাপ ঠিক হয়৤</p>\n<p>পাতার জায়গা বদলে গেলে ছবির মাপ আবার করুন৤ ডিজাইন বদলালে পুরোনো ছবির মাপ নাও মিলতে পারে৤ নতুন ডিজাইনে ছবি আবার তৈরি করুন৤</p>\n<p>পাতার জায়গা অনুযায়ী ছবির ফরম্যাটও বদলায়৤ হিরো ছবিতে WebP ভালো৤ আইকনে SVG ভালো৤ জায়গা অনুযায়ী ফরম্যাট বেছে নিন৤</p>\n<p>পাতার জায়গা অনুযায়ী ছবির ফাইলের আকার বদলায়৤ হিরো ছবিতে ২০০KB ঠিক আছে৤ থাম্বনেইলে ৫০KB যথেষ্ট৤ জায়গা অনুযায়ী আকার বেছে নিন৤</p>\n<p>পাতার জায়গা অনুযায়ী ছবি পরীক্ষা করুন৤ প্রতিটি জায়গায় ছবি কেমন দেখায় তা দেখুন৤ ছবি ভুল জায়গায় থাকলে ডিজাইন ভেঙে যায়৤</p>\n<p>পাতার জায়গার মাপের তালিকা দলের সবাইকে দিন৤ সবাই একই মাপ ব্যবহার করলে পাতার ছবি একরকম থাকে৤</p>\n<h2 id=\"srcset-basics\">Srcset-এর মূল বিষয়</h2>\n<p>Srcset মানে ব্রাউজারকে একই ছবির একাধিক আকার দেওয়া৤ ব্রাউজার পর্দা অনুযায়ী সঠিকটি বেছে নেয়৤</p>\n<p>ফোনে ছোট ছবি, ডেস্কটপে বড় ছবি লোড হয়৤ এতে মোবাইলে ডেটা বাঁচে৤</p>\n<p>অপটিমাইজার থেকে srcset কোড কপি করা যায়৤ এতে কোড লেখার সময় বাঁচে৤</p>\n<h2 id=\"image-seo\">ছবির SEO</h2>\n<p>ছবির ফাইলের নামে বর্ণনামূলক শব্দ রাখুন৤ এতে সার্চ ইঞ্জিন ছবিটি ভালো বোঝে৤</p>\n<p>Alt টেক্সট যোগ করুন৤ এটি SEO-তে সাহায্য করে আর স্ক্রিন রিডার ব্যবহারকারীদের কাজে লাগে৤</p>\n<p>দ্রুত লোড হওয়া পাতা SEO-তে ভালো স্কোর পায়৤ গতি একটি র‍্যাঙ্কিং বিষয়৤</p>\n<p>ছবির SEO মানে সার্চ ইঞ্জিন ছবি খুঁজে পায়৤ ছবির নামে কীওয়ার্ড থাকলে সার্চ ইঞ্জিন বুঝতে পারে৤ image123.jpg-এর বদলে বিষয় অনুযায়ী নাম দিন৤</p>\n<p>ছবির SEO-তে alt টেক্সট গুরুত্বপূর্ণ৤ alt টেক্সটে ছবির বিষয় লিখুন৤ alt টেক্সট ছাড়া ছবি সার্চে আসে না৤</p>\n<p>ছবির SEO-তে ফাইলের আকার গুরুত্বপূর্ণ৤ ছোট ছবির পাতা দ্রুত লোড হয়৤ গুগল দ্রুত পাতাকে ভালো র‍্যাঙ্ক দেয়৤</p>\n<p>ছবির SEO-তে ছবির চারপাশের লেখা গুরুত্বপূর্ণ৤ ছবির কাছের লেখায় বিষয় থাকলে সার্চ ইঞ্জিন ছবির বিষয় বোঝে৤</p>\n<p>ছবির SEO-তে সাইটম্যাপে ছবি যোগ করুন৤ সাইটম্যাপে ছবি থাকলে গুগল ছবি খুঁজে পায়৤ সাইটম্যাপ আপডেট করুন৤</p>\n<p>ছবির SEO-তে ছবির শিরোনাম লিখুন৤ শিরোনামে ছবির বিষয় থাকলে সার্চে ভালো ফল পাওয়া যায়৤</p>\n<p>ছবির SEO-তে ছবির সংখ্যা দেখুন৤ একটি পাতায় অনেক ছবি থাকলে পাতা ধীর হয়৤ প্রয়োজনীয় ছবি রাখুন৤</p>\n<p>ছবির SEO পরীক্ষা করতে গুগলে ছবি খুঁজুন৤ আপনার ছবি সার্চে আসে কিনা দেখুন৤ না আসলে নাম আর alt টেক্সট ঠিক করুন৤</p>\n<p>ছবির SEO একটি দীর্ঘমেয়াদি কাজ৤ নিয়মিত ছবি অপটিমাইজ করলে সার্চে ভালো ফল পাওয়া যায়৤</p>\n<h2 id=\"maintenance\">নিয়মিত রক্ষণাবেক্ষণ</h2>\n<p>মাসে একবার পুরোনো ছবির ওজন পরীক্ষা করুন৤ বড় ছবি পেলে অপটিমাইজ করে নিন৤</p>\n<p>নতুন ছবি আপলোডের আগে অপটিমাইজ করুন৤ পরে ঠিক করার চেয়ে আগে করা সহজ৤</p>\n<p>মাসে একবার গতি পরীক্ষা করুন৤ গতি কমে গেলে কারণ খুঁজে বের করুন৤</p>\n<h2 id=\"team-optimisation\">দলের অপটিমাইজেশন</h2>\n<p>দলে কাজ করলে সবাই একই নিয়ম মানুন৤ প্রিসেট, নাম আর ফোল্ডারের নিয়ম লিখে রাখুন৤</p>\n<p>একটি শেয়ার্ড ফোল্ডারে অপটিমাইজ করা ছবি রাখুন৤ এতে সবাই একই ফাইল ব্যবহার করে৤</p>\n<p>নতুন সদস্য এলে নিয়মটি দেখিয়ে দিন৤ এতে ভুল ছবি আপলোড হওয়ার আশঙ্কা কমে৤</p>\n<h2 id=\"common-speed-myths\">গতি নিয়ে ভুল ধারণা</h2>\n<p>অনেকেই ভাবেন শুধু ছবি ছোট করলেই পাতা দ্রুত হয়৤ আসলে স্ক্রিপ্ট আর ফন্টও গতি কমায়৤</p>\n<p>আরেকটি ভুল ধারণা হলো সব ছবি একই আকারে করা উচিত৤ প্রতিটি জায়গার জন্য আলাদা আকার দরকার৤</p>\n<p>গতি একটি সামগ্রিক বিষয়৤ ছবি, স্ক্রিপ্ট আর সার্ভার — সবই মিলে গতি ঠিক করে৤</p>\n<h2 id=\"final-check-speed\">গতির শেষ যাচাই</h2>\n<p>অপটিমাইজের পর গতি আবার পরীক্ষা করুন৤ আগের ফলের সঙ্গে তুলনা করুন৤</p>\n<p>ছবির মোট ওজন দেখুন৤ এক মেগাবাইটের নিচে রাখার চেষ্টা করুন৤</p>\n<p>ফোনে পাতাটি খুলে দেখুন৤ মোবাইলে গতি ঠিক আছে কি না নিশ্চিত করুন৤</p>\n<h2 id=\"keep-learning\">শিখতে থাকুন</h2>\n<p>নতুন ফরম্যাট আর পদ্ধতি আসছে৤ AVIF আর JPEG XL সম্পর্কে জানুন৤</p>\n<p>নিয়মিত গতি পরীক্ষা করুন৤ নতুন সমস্যা এলে কারণ খুঁজে বের করুন৤</p>\n<p>ভালো অভ্যাস ধরে রাখুন৤ প্রতিটি নতুন ছবি আপলোডের আগে অপটিমাইজ করুন৤</p>\n<p>Core Web Vitals জানতে পড়ুন <a href=\"/bn/blog/image-optimization-core-web-vitals\">ছবি অপটিমাইজেশন ও Core Web Vitals</a> আর পূর্ণ গাইডের জন্য <a href=\"/bn/blog/web-image-optimizer-guide\">ওয়েব ইমেজ অপটিমাইজার গাইড</a>৤ বড় ছবির জন্য <a href=\"/bn/image-200kb-te-compress-korun\">200KB কমপ্রেসর</a> ব্যবহার করুন৤</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ছবি অপটিমাইজ করলে পাতা কতটা দ্রুত হয়?","answer":"অনেকটা৤ বড় ছবি ছোট করলে পাতার মোট ওজন কমে, আর লোডের সময় কয়েক সেকেন্ড কমতে পারে৤ PageSpeed Insights দিয়ে আগে আর পরে তুলনা করুন৤"},{"question":"প্রথমে কোন ছবিগুলো অপটিমাইজ করব?","answer":"সবচেয়ে বড় ছবিগুলো প্রথমে করুন৤ PageSpeed Insights দেখিয়ে দেয় কোন ছবিগুলো সমস্যা তৈরি করছে৤ হিরো ছবি আর বড় গ্যালারির ছবি প্রথমে ঠিক করুন৤"},{"question":"Srcset কী, আর এটি কেন দরকার?","answer":"Srcset মানে ব্রাউজারকে একই ছবির একাধিক আকার দেওয়া৤ ব্রাউজার পর্দা অনুযায়ী সঠিকটি বেছে নেয়৤ ফোনে ছোট ছবি লোড হয়, এতে মোবাইলে ডেটা বাঁচে আর পাতা দ্রুত হয়৤"},{"question":"লেজি লোডিং কি সব ছবিতে ব্যবহার করব?","answer":"না৤ নিচের ছবিগুলোতে লেজি লোডিং ভালো, তবে হিরো ছবিতে নয়৤ হিরো ছবি প্রথমেই দেখা যায়, তাই তা দ্রুত লোড হওয়া উচিত৤"},{"question":"অপটিমাইজ করার পর গতি কীভাবে মাপব?","answer":"PageSpeed Insights বা GTmetrix দিয়ে পরীক্ষা করুন৤ অপটিমাইজের আগে আর পরে তুলনা করুন৤ ছবির মোট ওজন এক মেগাবাইটের নিচে রাখার চেষ্টা করুন৤"},{"question":"নতুন ছবি আপলোডের আগে কী করব?","answer":"আপলোডের আগে অপটিমাইজ করুন৤ মাপ ঠিক করুন, ফরম্যাট বেছে নিন, আর alt টেক্সট লিখে রাখুন৤ পরে ঠিক করার চেয়ে আগে করা সহজ৤"}];
